update public.projects
set
  has_case_study = true,
  case_study_document = $leads_case_study${"schemaVersion":2,"summary":"80+ website and store-management touchpoints depended on Google Sheets workflows that dropped over half of incoming lead activities. One owned lead service replaced that fragile handoff with consistent processing, durable activity records, custom activity-type workflows, downstream synchronization, and production recovery.","role":"Backend lead: Architecture, API design, integrations, infrastructure, production support, complete technical ownership.","heroVisual":{"type":"lead-network","eyebrow":"Touchpoint to owned record","title":"Many lead-activity sources, one controlled processing path.","description":"Website, store, and webhook activity converges into one Lead Service before owned storage and downstream delivery.","sourceLabel":"Capture surface","sourceStat":"80+","sourceStatLabel":"touchpoints","sources":[{"key":"website","name":"Website journeys","role":"Forms + product flows"},{"key":"stores","name":"Store platforms","role":"Assisted activity capture"},{"key":"webhooks","name":"Inbound webhooks","role":"JustDial + LeadSquared"}],"serviceLabel":"Lead Service","serviceRole":"Owned processing boundary","stages":[{"number":"01","title":"Capture","detail":"Phone + activity type"},{"number":"02","title":"Normalize","detail":"Shared field mapping"},{"number":"03","title":"Enrich","detail":"Nearest-store lookup"},{"number":"04","title":"Process","detail":"Custom activity workflows"}],"record":{"name":"MongoDB","role":"Owned database","detail":"Source activity + downstream task states"},"destinationLabel":"Downstream systems","destinations":[{"key":"leadsquared","name":"LeadSquared","role":"CRM + activities"},{"key":"webengage","name":"WebEngage","role":"Customer engagement"},{"key":"bigquery","name":"BigQuery","role":"Lead analytics"}],"layout":{"breakpoints":{"compactMax":650,"mobileMax":800,"tabletMax":1080},"canvas":{"width":1240,"height":620,"frameInset":1,"gridSize":28},"wide":{"sourceX":26,"destinationX":930,"laneWidth":284,"titleY":45,"statY":84,"sourceRuleY":100,"destinationRuleY":64,"nodeStartY":178,"nodeGap":93,"nodeWidth":284,"nodeHeight":79,"nodeTextX":17,"nodeTitleY":32,"nodeDetailY":57,"nodeAccentStartX":16,"nodeAccentEndX":40,"core":{"x":395,"y":26,"width":450,"height":568},"sourceConnectorPath":"M322 310H383","destinationConnectorPath":"M857 310H918"}}},"sections":[{"id":"outcome-snapshot","tone":"muted","eyebrow":"Outcome snapshot","title":"Lead-activity capture became dependable enough to support business growth.","type":"outcome-table","rows":[{"metric":"Lead-activity capture","before":"Less than 50%","after":"~99.5%","impact":"Nearly complete capture"},{"metric":"Monthly lead activities","before":"177,080 · Nov 2024","after":"410,087 · Jan 2025","impact":"~2.2x daily activity volume"},{"metric":"Lead-activity data operations","before":"Manual reconciliation","after":"Owned records + analytics","impact":"Almost all gathering work removed"}],"footer":{"value":"≈70%","label":"of revenue influenced by lead journeys","detail":"Dependable capture protected a commercially important acquisition channel instead of leaving it constrained by spreadsheet throughput."}},{"id":"operating-model-shift","tone":"base","eyebrow":"Operating model shift","title":"From spreadsheet transport to owned lead infrastructure.","type":"comparison","beforeLabel":"Before","afterLabel":"After","items":[{"before":"Google Sheets workflows dropped more than half of incoming lead activities under production volume.","after":"One NestJS service received lead activities from website, store, and webhook touchpoints."},{"before":"The business had no owned lead-activity database and depended on downstream tools for visibility.","after":"MongoDB retained activity payloads and downstream processing states in one controlled record."},{"before":"Analytics and propagation required manual searching across disconnected sources.","after":"LeadSquared, WebEngage, and BigQuery received data through one observable workflow."}]},{"id":"system-flow","tone":"muted","eyebrow":"System flow","title":"Every lead activity entered one owned processing path.","type":"system-flow","items":[{"step":"01","title":"Accept valuable data","detail":"Loose validation preserved incomplete lead activities instead of rejecting them before the business could act.","stat":"2","statLabel":"required fields"},{"step":"02","title":"Normalize by type","detail":"Shared mappings handled the common path while custom activities and source payloads used bounded type-specific processing.","stat":"80+","statLabel":"touchpoints"},{"step":"03","title":"Persist and distribute","detail":"The owned activity record kept the source payload and task states before data moved into sales, engagement, and analytics systems.","stat":"3","statLabel":"downstream systems"}]},{"id":"workflow-control","tone":"base","eyebrow":"Workflow control","title":"Failed downstream work remained visible and recoverable.","type":"workflow","intro":"Separate task states and a bounded retry window turned partial downstream failures into routine recovery work instead of silently lost lead activities.","steps":["Receive","Validate essentials","Map + enrich","Persist","Propagate","Record status","Retry failures"],"cards":[{"title":"Separate task states","detail":"LeadSquared, WebEngage, BigQuery, and other tasks retained independent success or failure fields.","keywords":["targeted recovery","task status","owned record"]},{"title":"Three-day retry window","detail":"A daily Kubernetes cron inspected recent records and repeated only the downstream work that remained incomplete.","keywords":["daily cron","bounded replay","failure recovery"]},{"title":"Operational visibility","detail":"Teams could inspect central records and analytics directly while routine recovery stayed automated.","keywords":["MongoDB","BigQuery","less manual work"]}]},{"id":"engineering-decisions","tone":"muted","eyebrow":"Engineering decisions","title":"The architecture protected capture without overengineering the first release.","type":"evidence-grid","cards":[{"title":"Preserve first","detail":"MongoDB retained structured and loosely structured fields so newly introduced payload data was not discarded while mappings evolved.","keywords":["MongoDB","evolving payloads","field retention"]},{"title":"Permissive validation","detail":"Only phone number and activity type were mandatory because incomplete activity data could still have commercial value.","keywords":["business value","loose schema","capture first"]},{"title":"Custom type workflows","detail":"Common lead activities reused one mapping path; LeadSquared custom activities and source exceptions used explicit type-based processing.","keywords":["shared mapping","custom activities","bounded exceptions"]},{"title":"Open, rate-limited API","detail":"The ingestion boundary stayed open for distributed business touchpoints while IP-based limits constrained abuse.","keywords":["IP rate limits","open ingestion","touchpoint access"]}]},{"id":"production-proof","tone":"base","eyebrow":"Production proof","title":"The system handled sales traffic—and improved when an assumption failed.","type":"evidence-grid","cards":[{"title":"626,470 lead activities","detail":"The owned service sustained more than 626K lead-activity records in a measured 30-day period.","keywords":["30 days","owned records","production scale"]},{"title":"3,611,900 requests","detail":"Webhook-heavy traffic was sustained in the same period; repeated LeadSquared activity callbacks accounted for most requests.","keywords":["webhook traffic","contextual metric","LeadSquared"]},{"title":"Scaling assumptions corrected","detail":"A 75% trigger and 60-second scale-down window caused spike intolerance. The policy moved to 60% CPU with a 300-second stabilization window.","keywords":["2–10 pods","60% CPU","300s stabilization"]},{"title":"Observable by design","detail":"SigNoz exposed searchable logs and traces with alerts for downtime, P90 degradation, elevated 500s, and elevated 400s.","keywords":["SigNoz","P90","logs + traces"]}],"circuitAnchor":"section-bottom"},{"id":"capabilities-demonstrated","tone":"muted","eyebrow":"Capabilities demonstrated","title":"Lead infrastructure carried through production ownership.","type":"capability-band","showProjectCapabilities":true,"primaryActionLabel":"Discuss a Project","secondaryActionLabel":"Visit Live Site"}]}$leads_case_study$::jsonb,
  updated_at = timezone('utc', now())
where slug = 'leads-management-the-sleep-company';

update public.projects
set
  category = 'Freelance - Cross-Platform - Payments and Notifications',
  title = 'Payments and notification journeys across web, Android, and iOS',
  challenge = $$A new hospitality hiring product needed two release-critical capabilities to behave consistently across three client platforms.$$,
  delivery = $$End-to-end Razorpay payments and event-driven push notifications were delivered through one React and Capacitor application, including backend verification, platform delivery, and deep-link routing.$$,
  capabilities = array[
    'Cross-platform feature delivery',
    'Payment integration',
    'Push notifications',
    'Backend APIs',
    'Hasura events',
    'Deep linking',
    'Third-party package adaptation',
    'Production testing'
  ],
  metrics = '[{"value":"3","label":"client platforms"},{"value":"2","label":"production features"},{"value":"1","label":"shared payment flow"}]'::jsonb,
  has_case_study = true,
  case_study_document = $horecah_case_study${"schemaVersion":2,"summary":"Horecah's first release needed payments and transactional notifications to work as complete product journeys across web, Android, and iOS. During a one-month freelance engagement, both capabilities were delivered end to end through the shared React and Capacitor application, its Node.js backend, and Hasura-backed PostgreSQL data layer.","role":"Freelance feature engineer: End-to-end ownership of Razorpay payments and push notifications across web, Android, and iOS.","heroVisual":{"type":"cross-platform-features","eyebrow":"Contribution boundary","title":"One shared client, two owned features, three production platforms.","description":"Web, Android, and iOS share one React and Capacitor client that branches into the two end-to-end feature boundaries owned during the engagement: Razorpay payments and event-driven notification journeys.","platforms":["Web","Android","iOS"],"sharedCore":{"name":"React + Capacitor","role":"One shared client application"},"features":[{"key":"payments","name":"Razorpay payments","role":"End-to-end payment boundary","steps":["Backend order creation","Cross-platform Razorpay checkout","Signature verification + webhooks"]},{"key":"notifications","name":"Push notifications","role":"Automatic product journeys","steps":["Hasura event trigger","FCM / APNs delivery","Destination-aware deep-link routing"]}],"layout":{"breakpoints":{"stackMax":650,"fullCoreMax":1080}}},"sections":[{"id":"feature-scope","tone":"muted","eyebrow":"Feature scope","title":"Two product capabilities, completed across three client platforms.","type":"system-flow","items":[{"step":"01","title":"Create and launch checkout","detail":"The Node.js backend created Razorpay orders while one React and Capacitor checkout contract served web, Android, and iOS.","stat":"3","statLabel":"client platforms"},{"step":"02","title":"Verify independently","detail":"Backend signature verification supported the live checkout result; Razorpay webhooks preserved verification when the client flow stopped.","stat":"2","statLabel":"verification paths"},{"step":"03","title":"Complete the journey","detail":"Hasura events triggered notifications through FCM or APNs, with route data that opened the correct React screen after a tap.","stat":"1","statLabel":"routing contract"}]},{"id":"payment-integration","tone":"base","eyebrow":"Payment integration","title":"The shared payment flow required repairing the plugin boundary.","type":"evidence-grid","cards":[{"title":"Production-ready Capacitor fork","detail":"Razorpay's official Capacitor plugin did not integrate cleanly with the production setup. Its TypeScript toolchain, bundle format, checkout types, package identity, distributable build, and CocoaPods identity were adapted in a maintained Horecah fork.","keywords":["Capacitor 6","TypeScript","CocoaPods"]},{"title":"One implementation across clients","detail":"The repaired package kept web and native checkout behind one application-level contract instead of creating separate payment implementations for each platform.","keywords":["shared contract","web + native","Razorpay"]},{"title":"Two failure boundaries","detail":"Checkout responses were verified on the backend for immediate completion, while server-to-server webhooks reconciled payment state independently of the active client.","keywords":["signature verification","webhooks","reconciliation"]}]},{"id":"notification-delivery","tone":"muted","eyebrow":"Notification delivery","title":"A notification only worked when it returned the user to the right journey.","type":"evidence-grid","cards":[{"title":"Event-driven delivery","detail":"Hasura events connected product activity to automatic notification journeys instead of requiring manual sends.","keywords":["Hasura events","automatic triggers","PostgreSQL"]},{"title":"Platform-aware routing","detail":"The backend stored device tokens and selected FCM or APNs delivery according to the registered client platform.","keywords":["device tokens","FCM","APNs"]},{"title":"Consistent deep links","detail":"A shared payload structure carried the destination data needed for notification taps to open the intended React screen consistently on web, Android, and iOS.","keywords":["payload contract","deep links","cross-platform"]},{"title":"Web push restored","detail":"An initial web-push integration failure was diagnosed and resolved as part of bringing the complete notification path to release readiness.","keywords":["web push","integration debugging","release path"]}]},{"id":"production-readiness","tone":"base","eyebrow":"Production readiness","title":"Both features shipped with Horecah's first production release.","type":"evidence-grid","cards":[{"title":"Real-platform verification","detail":"Payments and notifications were exercised in web browsers and on physical Android and iOS devices, including foreground, background, and terminated application states.","keywords":["real devices","browser checks","app lifecycle"]},{"title":"Failure paths covered","detail":"Cancelled and failed payments, invalid verification, expired device tokens, and unsuccessful notification delivery were handled as part of the feature boundary.","keywords":["error handling","token lifecycle","payment failures"]},{"title":"Production v1 launch","detail":"The payment gateway and automated notification journeys launched with the complete first version of the product.","keywords":["v1 launch","payments","production ready"]}],"circuitAnchor":"section-bottom"},{"id":"capabilities-demonstrated","tone":"muted","eyebrow":"Capabilities demonstrated","title":"Cross-platform features carried through their complete production boundary.","type":"capability-band","showProjectCapabilities":true,"primaryActionLabel":"Discuss a Project","secondaryActionLabel":"Visit Live Site"}]}$horecah_case_study$::jsonb,
  updated_at = timezone('utc', now())
where slug = 'horecah';
